from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    result = []
    group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        group += char

        if open_count == 0:
            result.append(group)  # Step 3: Separate each group into distinct strings
            group = ""

    return result

